SELECT s.Name, s.Country
FROM singer s
WHERE s.Song_Name LIKE '%Hey%';

SELECT COUNT(*) AS car_count
FROM cars_data
WHERE Cylinders > 6;

SELECT MAX(CAST(MPG AS DOUBLE)) AS max_mpg
FROM cars_data
WHERE Cylinders = 8 OR Year < 1980;

SELECT Country
FROM airlines
WHERE Airline = 'JetBlue Airways';

SELECT Abbreviation
FROM airlines
WHERE Airline = 'JetBlue Airways';

SELECT *
FROM airlines
WHERE Abbreviation = 'UAL';

SELECT COUNT(*) AS usa_airline_count
FROM airlines
WHERE Country = 'USA';

SELECT AirportName
FROM airports
WHERE City = 'Aberdeen';

SELECT AirportName
FROM airports
WHERE City = 'Aberdeen';

SELECT COUNT(*) AS flight_count
FROM flights
WHERE DestAirport = 'ATO';

SELECT COUNT(*) AS CV_Template_Count
FROM Templates
WHERE Template_Type_Code = 'CV';

SELECT Name
FROM teacher
WHERE Hometown <> 'Little Lever Urban District';

SELECT Name
FROM teacher
WHERE Age IN (32, 33);

SELECT Open_Year, Num_of_Staff
FROM museum
WHERE Name = 'Plaza Museum';

SELECT first_name, birth_date
FROM players
WHERE country_code = 'USA';

SELECT name, result
FROM battle
WHERE bulgarian_commander <> 'Boril';

SELECT department_description
FROM Departments
WHERE department_name ILIKE '%computer%';

SELECT *
FROM Sections
WHERE section_name = 'h';

SELECT *
FROM Cartoon
WHERE Directed_by = 'Ben Jones';

SELECT Title
FROM Cartoon
WHERE Directed_by = 'Ben Jones';

SELECT Name
FROM people
WHERE Nationality <> 'Russia';

SELECT COUNT(*) AS republic_countries
FROM country
WHERE LOWER(GovernmentForm) LIKE '%republic%';

SELECT Name
FROM conductor
ORDER BY Age ASC;

SELECT Name
FROM conductor
WHERE Nationality <> 'USA';

SELECT ID
FROM Highschooler
WHERE name = 'Kyle';

SELECT DISTINCT first_name
FROM (
    SELECT first_name FROM Professionals
    UNION ALL
    SELECT first_name FROM Owners
) AS all_people
WHERE first_name NOT IN (
    SELECT name FROM Dogs
);

SELECT Name
FROM singer
WHERE Birth_Year IN (1948, 1949);
